(async()=>{
const g=__game; const wait=(ms)=>new Promise(r=>setTimeout(r,ms));
const until=async(f,ms=30000)=>{const t=performance.now(); while(!f()){ if(performance.now()-t>ms) return false; await wait(100);} return true;};
if(!window.__bot) __autoplay();
const out=[];
async function trial(n, depth, seed){
  __bot.paused=true; await wait(200);
  g.scene.getScenes(true).filter(s=>s.scene.key!=='Notify').forEach(s=>s.scene.stop());
  const run=__run.start({heroId:'rowan',seed}); run.mutator=undefined; run.depth=depth; run.floor=1; run.level=30;
  for(let i=0;i<n;i++){ const o=__run.boonOffers(run,3)[0]; if(o) __run.addBoon(run,o.def.id); }
  g.scene.start('RunMap'); await until(()=>g.scene.isActive('RunMap'));
  await wait(600);
  const m=g.scene.getScene('RunMap'); const c=__run.choices(run); const node=c.find(x=>x.kind==='combat')||c[0]; node.kind='combat'; m.select(node);
  await until(()=>g.scene.isActive('Room') && g.scene.getScene('Room').player);
  const r=g.scene.getScene('Room'); const inv=setInterval(()=>{ if(r.player){ r.player.invuln=5; r.player.hp=r.player.maxHp; } },100);
  __bot.paused=false;
  const ok=await until(()=>r.cleared, 240000);
  clearInterval(inv); __bot.paused=true;
  out.push({n, depth, seed, ok, roomTime:+r.roomTime.toFixed(1), kills:run.kills, boons:run.boons.length});
}
for(const n of [0,12,24]) for(const seed of [11,12]) await trial(n,3,seed);
return JSON.stringify(out);
})()
